using System;using System.IO;using System.IO.Compression;using System.Xml;using System.Collections;using System.Text;using System.Text.RegularExpressions;
public static class StudentArchive {
 static string Col(int n){string s="";while(n>0){n--;s=(char)('A'+n%26)+s;n/=26;}return s;}
 static string Text(string s){s=Regex.Replace(s??"",@"_x[0-9A-Fa-f]{4}_",m=>"_x005F_"+m.Value.Substring(1));var b=new StringBuilder();foreach(char c in s){if(c<32&&c!='\n'&&c!='\r'&&c!='\t')b.Append("_x"+((int)c).ToString("X4")+"_");else b.Append(c);}return b.ToString();}
 static void Part(ZipArchive z,string path,string content){using(var w=new StreamWriter(z.CreateEntry(path).Open(),new UTF8Encoding(false)))w.Write(content);}
 public static Hashtable Formulas(string path){var result=new Hashtable();using(var z=ZipFile.OpenRead(path)){
 var wb=new XmlDocument();wb.XmlResolver=null;using(var f=z.GetEntry("xl/workbook.xml").Open())wb.Load(f);var rel=new XmlDocument();rel.XmlResolver=null;using(var f=z.GetEntry("xl/_rels/workbook.xml.rels").Open())rel.Load(f);var targets=new Hashtable();foreach(XmlNode n in rel.DocumentElement.ChildNodes)targets[n.Attributes["Id"].Value]=n.Attributes["Target"].Value;
 foreach(XmlNode sh in wb.GetElementsByTagName("sheet")){string rid=sh.Attributes["id","http://schemas.openxmlformats.org/officeDocument/2006/relationships"].Value;string target=(string)targets[rid];target=target.StartsWith("/")?target.TrimStart('/'):("xl/"+target);var doc=new XmlDocument();doc.XmlResolver=null;using(var f=z.GetEntry(target).Open())doc.Load(f);foreach(XmlNode cell in doc.GetElementsByTagName("c")){foreach(XmlNode child in cell.ChildNodes){if(child.LocalName=="f")result[sh.Attributes["name"].Value+"!"+cell.Attributes["r"].Value]=child.InnerText;else if(child.LocalName=="v")result["raw:"+sh.Attributes["name"].Value+"!"+cell.Attributes["r"].Value]=child.InnerText;}}}
 }return result;}
 public static void Write(string path,IList sheets){
 using(var fs=new FileStream(path,FileMode.CreateNew))using(var z=new ZipArchive(fs,ZipArchiveMode.Create)){
 var types=new StringBuilder("<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/styles.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml\"/>");
 var wb=new StringBuilder("<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets>");var rel=new StringBuilder("<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\">");int i=0;
 foreach(Hashtable sh in sheets){i++;string name=(string)sh["name"];var rows=(IList)sh["rows"];var headers=(IList)sh["headers"];if(rows.Count>1048575)throw new Exception("Excel row limit: "+name);
 types.Append("<Override PartName=\"/xl/worksheets/sheet"+i+".xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/>");wb.Append("<sheet name=\""+System.Security.SecurityElement.Escape(name)+"\" sheetId=\""+i+"\" r:id=\"rId"+i+"\"/>");rel.Append("<Relationship Id=\"rId"+i+"\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet"+i+".xml\"/>");
 using(var stream=z.CreateEntry("xl/worksheets/sheet"+i+".xml").Open())using(var x=XmlWriter.Create(stream,new XmlWriterSettings{Encoding=new UTF8Encoding(false),CheckCharacters=true,NewLineHandling=NewLineHandling.Entitize})){
 x.WriteStartElement("worksheet","http://schemas.openxmlformats.org/spreadsheetml/2006/main");x.WriteStartElement("sheetViews");x.WriteStartElement("sheetView");x.WriteAttributeString("workbookViewId","0");x.WriteStartElement("pane");x.WriteAttributeString("ySplit","1");x.WriteAttributeString("topLeftCell","A2");x.WriteAttributeString("state","frozen");x.WriteEndElement();x.WriteEndElement();x.WriteEndElement();x.WriteStartElement("cols");for(int c=1;c<=headers.Count;c++){x.WriteStartElement("col");x.WriteAttributeString("min",c.ToString());x.WriteAttributeString("max",c.ToString());x.WriteAttributeString("width",((string)headers[c-1]).Contains("내용")?"72":"23");x.WriteAttributeString("customWidth","1");x.WriteEndElement();}x.WriteEndElement();x.WriteStartElement("sheetData");
 for(int r=0;r<=rows.Count;r++){IList cells=r==0?headers:(IList)rows[r-1];if(cells.Count!=headers.Count)throw new Exception("Export column alignment: "+name);x.WriteStartElement("row");x.WriteAttributeString("r",(r+1).ToString());for(int c=0;c<cells.Count;c++){string v=Convert.ToString(cells[c],System.Globalization.CultureInfo.InvariantCulture);if(v.Length>32767)throw new Exception("Unsplit cell exceeds Excel limit");x.WriteStartElement("c");x.WriteAttributeString("r",Col(c+1)+(r+1));x.WriteAttributeString("t","inlineStr");x.WriteAttributeString("s",r==0?"1":"0");x.WriteStartElement("is");x.WriteStartElement("t");x.WriteAttributeString("xml","space",null,"preserve");x.WriteString(Text(v));x.WriteEndElement();x.WriteEndElement();x.WriteEndElement();}x.WriteEndElement();}x.WriteEndElement();x.WriteStartElement("autoFilter");x.WriteAttributeString("ref","A1:"+Col(headers.Count)+(rows.Count+1));x.WriteEndElement();x.WriteEndElement();}}
 wb.Append("</sheets></workbook>");types.Append("</Types>");rel.Append("<Relationship Id=\"styles\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles\" Target=\"styles.xml\"/></Relationships>");Part(z,"[Content_Types].xml",types.ToString());Part(z,"xl/workbook.xml",wb.ToString());Part(z,"xl/_rels/workbook.xml.rels",rel.ToString());Part(z,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");Part(z,"xl/styles.xml","<styleSheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><fonts count=\"2\"><font><sz val=\"11\"/><name val=\"맑은 고딕\"/></font><font><b/><color rgb=\"FFFFFFFF\"/><sz val=\"11\"/><name val=\"맑은 고딕\"/></font></fonts><fills count=\"3\"><fill><patternFill patternType=\"none\"/></fill><fill><patternFill patternType=\"gray125\"/></fill><fill><patternFill patternType=\"solid\"><fgColor rgb=\"FF1A365D\"/><bgColor indexed=\"64\"/></patternFill></fill></fills><borders count=\"1\"><border/></borders><cellStyleXfs count=\"1\"><xf/></cellStyleXfs><cellXfs count=\"2\"><xf fontId=\"0\" fillId=\"0\" borderId=\"0\" numFmtId=\"49\" applyAlignment=\"1\"><alignment vertical=\"top\" wrapText=\"1\"/></xf><xf fontId=\"1\" fillId=\"2\" borderId=\"0\" applyFont=\"1\" applyFill=\"1\"><alignment vertical=\"top\" wrapText=\"1\"/></xf></cellXfs></styleSheet>");
 }}
}